<section aria-labelledby="automation-webhook-inventory"><h2 id="automation-webhook-inventory">{{ __('Webhooks') }}</h2>
    <label for="webhook-search">{{ __("Search webhooks") }}</label><input id="webhook-search" type="search" wire:model.live.debounce.300ms="search"><ul>@forelse($webhooks as $webhook)<li wire:key="automation-webhook-{{ $webhook->getKey() }}">{{ $webhook->name }} — {{ $webhook->status }} <form wire:submit="update('{{ $webhook->getKey() }}', null)"><input aria-label="{{ __('Webhook name') }}" wire:model="edits.{{ $webhook->getKey() }}.name" value="{{ $webhook->name }}"><input aria-label="{{ __('Webhook URL') }}" wire:model="edits.{{ $webhook->getKey() }}.url" value="{{ $webhook->url }}"><input aria-label="{{ __('Retry limit') }}" type="number" wire:model="edits.{{ $webhook->getKey() }}.retry_limit" value="{{ $webhook->retry_limit }}"><button type="submit">{{ __('Save') }}</button></form> @if ($webhook->status === 'active') <button type="button" wire:click="pause('{{ $webhook->getKey() }}')">{{ __('Pause') }}</button> @elseif (in_array($webhook->status, ['paused', 'failed'], true)) <button type="button" wire:click="resume('{{ $webhook->getKey() }}')">{{ __('Resume') }}</button> @endif</li>@empty<li>{{ __('No webhooks found.') }}</li>@endforelse</ul>{{ $webhooks->links() }}</section>
